EXECUTE IMMEDIATE $$
DECLARE answer VARCHAR DEFAULT 'no';
BEGIN
    IF (1 = 1) THEN
        answer := 'yes';
    END IF;
    RETURN :answer;
END
$$

EXECUTE IMMEDIATE $$
DECLARE result VARCHAR DEFAULT 'none';
BEGIN
    IF (1 = 2) THEN
        result := 'if-branch';
    ELSE
        result := 'else-branch';
    END IF;
    RETURN :result;
END
$$

EXECUTE IMMEDIATE $$
DECLARE total INT DEFAULT 0;
BEGIN
    LET cur CURSOR FOR SELECT 1 AS n UNION ALL SELECT 1 UNION ALL SELECT 1;
    FOR rec IN cur DO
        total := :total + rec.N;
    END FOR;
    CLOSE cur;
    RETURN :total;
END
$$

